def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    colors = {v for row in grid for v in row if v != bg}
    # The marker color occurs as isolated single cells; the remaining non-background
    # cells form the object to copy.
    def components(color_set):
        seen = set(); result = []
        for r in range(h):
            for c in range(w):
                if grid[r][c] not in color_set or (r,c) in seen: continue
                stack=[(r,c)]; seen.add((r,c)); comp=[]
                while stack:
                    y,x=stack.pop(); comp.append((y,x,grid[y][x]))
                    for q in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                        yy,xx=q
                        if 0<=yy<h and 0<=xx<w and q not in seen and grid[yy][xx] in color_set:
                            seen.add(q); stack.append(q)
                result.append(comp)
        return result
    # Most ARC examples have one marker color distinct from the multicolor source.
    marker_color = None
    for color in colors:
        comps = components({color})
        if len(comps) >= 2 and all(len(x)==1 for x in comps):
            marker_color=color; break
    if marker_color is None:
        return [row[:] for row in grid]
    markers=[(r,c) for r in range(h) for c in range(w) if grid[r][c]==marker_color]
    objcolors=colors-{marker_color}
    comps=components(objcolors)
    source=max(comps,key=len)
    minr=min(p[0] for p in source); maxr=max(p[0] for p in source)
    minc=min(p[1] for p in source); maxc=max(p[1] for p in source)
    ar=(minr+maxr)//2; ac=(minc+maxc)//2
    pattern=[(r-ar,c-ac,v) for r,c,v in source]
    out=[row[:] for row in grid]
    for mr,mc in markers:
        for dr,dc,v in pattern:
            y,x=mr+dr,mc+dc
            if 0<=y<h and 0<=x<w: out[y][x]=v
    return out
